import java.util.*;

public class Main {
    public static void main(String[] args) {
        MailService mail = new MailService();

        // A genuine, legitimate email: low spam score, delivered to the inbox.
        mail.deliverEmail("email-1", "boss@company.com", "Meeting tomorrow", "Let's meet at 3pm to discuss the roadmap.");
        System.out.println("email-1 labels after delivery: " + mail.labelsOf("email-1"));

        // An obviously spammy email: suspicious sender, urgent subject, excessive links, high spam score.
        mail.deliverEmail("email-2", "winner@free-prizes.biz", "URGENT: You have WON FREE MONEY",
            "Click here http://x.co http://x.co http://x.co http://x.co http://x.co to claim your prize now!!!");
        System.out.println("email-2 labels after delivery: " + mail.labelsOf("email-2"));

        // Apply additional, simultaneous labels to email-1: labels are not mutually exclusive.
        mail.applyLabel("email-1", "Work");
        mail.applyLabel("email-1", "Important");
        System.out.println("email-1 labels after tagging Work and Important: " + mail.labelsOf("email-1"));

        // Archive email-1: only the Inbox label is removed, the email and its other labels remain.
        mail.removeLabel("email-1", "INBOX");
        System.out.println("email-1 labels after archiving (Inbox removed, others remain): " + mail.labelsOf("email-1"));

        System.out.println("Emails currently in Inbox (should exclude archived email-1 and spam email-2): " + mail.emailsWithLabel("INBOX"));
        System.out.println("Emails currently labeled Work (should still include email-1): " + mail.emailsWithLabel("Work"));
        System.out.println("Emails currently labeled Spam (should include email-2): " + mail.emailsWithLabel("SPAM"));
    }
}

