    Set<String> labels = new LinkedHashSet<>();

    Email(String emailId) {
        this.emailId = emailId;
    }
}

// Scores incoming email for spam signals, applies an initial label, and
// manages a many-to-many labels-as-tags model where an email is stored
// exactly once but can carry any number of simultaneous, non-exclusive labels.
class MailService {
    private final Map<String, Email> emails = new LinkedHashMap<>();
    private static final double SPAM_THRESHOLD = 5.0;

    void deliverEmail(String emailId, String sender, String subject, String body) {
        double score = computeSpamScore(sender, subject, body);
        Email email = new Email(emailId);
        email.labels.add(score >= SPAM_THRESHOLD ? "SPAM" : "INBOX"); // initial label based on the spam score
        emails.put(emailId, email);
    }

    // A simplified, real point-based spam score combining a few genuine signals.
    private double computeSpamScore(String sender, String subject, String body) {
        double score = 0;
        if (sender.contains("free-prizes") || sender.contains("winner@")) score += 3; // suspicious sender pattern
        String upperSubject = subject.toUpperCase();
        if (upperSubject.contains("URGENT") || upperSubject.contains("FREE MONEY")) score += 2; // suspicious phrasing
        int linkCount = body.split("http").length - 1; // crude link count by counting "http" occurrences
        if (linkCount >= 3) score += 3; // excessive link density
        return score;
    }

    void applyLabel(String emailId, String label) {
        emails.get(emailId).labels.add(label); // additive: never affects any other label already applied
    }

    void removeLabel(String emailId, String label) {
        emails.get(emailId).labels.remove(label); // only removes this one label; the email and its other labels are untouched
    }

    Set<String> labelsOf(String emailId) {
        return emails.get(emailId).labels;
    }

    List<String> emailsWithLabel(String label) {
        List<String> result = new ArrayList<>();
        for (Email email : emails.values()) {
            if (email.labels.contains(label)) result.add(email.emailId);
        }
        return result;
    }
}

