#include <iostream>
#include <map>
#include <set>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

// One stored email: its recipient-facing labels, a many-to-many set rather
// than a single, mutually exclusive folder assignment.
struct Email {
    string emailId;
    set<string> labels;
};

// Scores incoming email for spam signals, applies an initial label, and
// manages a many-to-many labels-as-tags model where an email is stored
// exactly once but can carry any number of simultaneous, non-exclusive labels.
class MailService {
public:
    static constexpr double SPAM_THRESHOLD = 5.0;

    void deliverEmail(const string& emailId, const string& sender, const string& subject, const string& body) {
        double score = computeSpamScore(sender, subject, body);
        Email email;
        email.emailId = emailId;
        email.labels.insert(score >= SPAM_THRESHOLD ? "SPAM" : "INBOX"); // initial label based on the spam score
        emails[emailId] = email;
    }

    void applyLabel(const string& emailId, const string& label) {
        emails[emailId].labels.insert(label); // additive: never affects any other label already applied
    }

    void removeLabel(const string& emailId, const string& label) {
        emails[emailId].labels.erase(label); // only removes this one label; the email and its other labels are untouched
    }

    set<string> labelsOf(const string& emailId) {
        return emails[emailId].labels;
    }

    vector<string> emailsWithLabel(const string& label) {
        vector<string> result;
        for (const auto& entry : emails) {
            if (entry.second.labels.count(label)) result.push_back(entry.first);
        }
        return result;
    }

private:
    map<string, Email> emails;

    // A simplified, real point-based spam score combining a few genuine signals.
    double computeSpamScore(const string& sender, const string& subject, const string& body) {
        double score = 0;
        if (sender.find("free-prizes") != string::npos || sender.find("winner@") != string::npos) score += 3; // suspicious sender
        string upperSubject = subject;
        transform(upperSubject.begin(), upperSubject.end(), upperSubject.begin(), ::toupper);
        if (upperSubject.find("URGENT") != string::npos || upperSubject.find("FREE MONEY") != string::npos) score += 2; // suspicious phrasing
        int linkCount = 0;
        size_t pos = 0;
        while ((pos = body.find("http", pos)) != string::npos) { linkCount++; pos += 4; } // crude link count
        if (linkCount >= 3) score += 3; // excessive link density
        return score;
    }
};

void printSet(const string& label, const set<string>& s) {
    cout << label << ": {";
    bool first = true;
    for (const auto& item : s) {
        if (!first) cout << ", ";
        cout << item;
        first = false;
    }
    cout << "}" << endl;
}

int main() {
    MailService mail;

    // A genuine, legitimate email: low spam score, delivered to the inbox.
    mail.deliverEmail("email-1", "boss@company.com", "Meeting tomorrow", "Let's meet at 3pm to discuss the roadmap.");
    printSet("email-1 labels after delivery", mail.labelsOf("email-1"));

    // An obviously spammy email: suspicious sender, urgent subject, excessive links, high spam score.
    mail.deliverEmail("email-2", "winner@free-prizes.biz", "URGENT: You have WON FREE MONEY",
        "Click here http://x.co http://x.co http://x.co http://x.co http://x.co to claim your prize now!!!");
    printSet("email-2 labels after delivery", mail.labelsOf("email-2"));

    // Apply additional, simultaneous labels to email-1: labels are not mutually exclusive.
    mail.applyLabel("email-1", "Work");
    mail.applyLabel("email-1", "Important");
    printSet("email-1 labels after tagging Work and Important", mail.labelsOf("email-1"));

    // Archive email-1: only the Inbox label is removed, the email and its other labels remain.
    mail.removeLabel("email-1", "INBOX");
    printSet("email-1 labels after archiving (Inbox removed, others remain)", mail.labelsOf("email-1"));

    cout << "Emails currently in Inbox (should exclude archived email-1 and spam email-2): ";
    for (const auto& e : mail.emailsWithLabel("INBOX")) cout << e << " ";
    cout << endl;

    cout << "Emails currently labeled Work (should still include email-1): ";
    for (const auto& e : mail.emailsWithLabel("Work")) cout << e << " ";
    cout << endl;

    cout << "Emails currently labeled Spam (should include email-2): ";
    for (const auto& e : mail.emailsWithLabel("SPAM")) cout << e << " ";
    cout << endl;

    return 0;
}

